#include <stdio.h>

int main() {
    int myInteger = 42;
    char myCharacter = 'A';

    printf("Integer: %d\n", myInteger);
    // Output:
    // Integer: 42

    printf("Character: %c\n", myCharacter);
    // Output:
    // Character: A

    return 0;
}

.data
// Format string for printing an integer
format1:   .string  "Integer: %d\n"

// Format string for printing a character
format2:   .string  "Character: %c\n"

// Pseudo-ops and directives
main:
    // Program prologue
    ..
    ldr x0, =format1
    ..

    ldr x0, =format2
    ..

    // program epilogue
